var raw  = $input.first().json;
var body = (raw.body != null) ? raw.body : raw;
var data;
try   { data = (typeof body === 'string') ? JSON.parse(body) : body; }
catch (e) { data = {}; }

if (data.error && typeof data.error === 'string') {
  var match = data.error.match(/\{[\s\S]*\}/);
  if (match) {
    try { data = JSON.parse(match[0]); } catch(e) {}
  }
}

var isCmResponse = (data.accepted != null);
var isHttpError  = (!isCmResponse && data.statusCode != null && data.error != null);

var accepted    = false;
var sucessoJson;
var erroJson;

if (isCmResponse) {
  accepted = (data.accepted === true || data.accepted === 'true');

  if (accepted) {
    sucessoJson = JSON.stringify({
      status:  'success',
      accepted: true,
      message: String(data.message || '-'),
      ticket:  String(data.ticket  || '-')
    });
  } else {
    erroJson = JSON.stringify({
      status:    'error',
      errorType: 'accepted_false',
      message:   'Solicitacao recusada pelo provedor.',
      detail:    String(data.message || '-')
    });
  }

} else if (isHttpError) {
  erroJson = JSON.stringify({
    status:     'error',
    errorType:  'http_error',
    message:    String(data.message || 'Erro desconhecido'),
    detail:     'Codigo: ' + String(data.statusCode) + ' | ' + String(data.error),
    statusCode: data.statusCode
  });

} else {
  erroJson = JSON.stringify({
    status:    'error',
    errorType: 'unknown',
    message:   'Estrutura de resposta nao reconhecida.',
    raw:       data
  });
}

return [{ json: {
  accepted:   accepted,
  sucessoJson: sucessoJson || null,
  erroJson:   erroJson    || null
} }];
